let current='en';
let applying=false;
const textCache=new WeakMap();
const attrCache=new WeakMap();

function preferred(){
  try{return localStorage.getItem(KEY)==='ar'?'ar':'en';}catch(e){return 'en';}
}
function save(v){try{localStorage.setItem(KEY,v);}catch(e){}}

function compact(s){return String(s||'').replace(/\s+/g,' ').trim();}
function moneyArabic(s){
  return String(s)
    .replace(/^From AED\s*/i,'ابتداءً من ')
    .replace(/^\+\s*AED\s*/i,'+ ')
    .replace(/^AED\s*/i,'')
    .replace(/\s*\/\s*month$/i,' / شهرياً')
    .replace(/\s*\/\s*project$/i,' / للمشروع')
    .replace(/\s*\/\s*2 hours$/i,' / ساعتين')
    .replace(/\s*one-time$/i,' مرة واحدة')
    + (/^((From )?AED|\+\s*AED)/i.test(String(s)) && !/درهم/.test(String(s)) ? ' درهم' : '');
}

function dyn(raw){
  const s=compact(raw);
  if(!s) return raw;
  if(T[s]!==undefined) return T[s];

  let m=s.match(/^Planning range:\s*(.+)$/i);
  if(m) return 'النطاق التقديري: '+moneyArabic(m[1]);

  m=s.match(/^(\d+(?:\.\d+)?)\s+hours$/i);
  if(m) return m[1]+' ساعات';

  m=s.match(/^(\d+)\s+extra applications$/i);
  if(m) return m[1]+' تطبيقات إضافية';

  m=s.match(/^(\d+)\s+extra content assets$/i);
  if(m) return m[1]+' مواد محتوى إضافية';

  m=s.match(/^(\d+)\s+creator sessions?$/i);
  if(m) return m[1]+' جلسات للمبدعين';

  m=s.match(/^(\d+)\s+photos above included volume$/i);
  if(m) return m[1]+' صور إضافية فوق العدد المشمول';

  m=s.match(/^(\d+)\s+extra Reels?$/i);
  if(m) return m[1]+' ريلز إضافية';

  m=s.match(/^View\s+(.+)\s+photograph$/i);
  if(m) return 'عرض صورة '+(T[m[1]]||m[1]);

  m=s.match(/^Play\s+(.+)$/i);
  if(m) return 'تشغيل '+(T[m[1]]||m[1]);

  if(/^(From )?AED\s/i.test(s) || /^\+\s*AED\s/i.test(s)) return moneyArabic(s);

  if(s.includes(' + ')) return s.split(' + ').map(x=>T[compact(x)]||compact(x)).join(' + ');

  m=s.match(/^(\d+) × (.+)$/);
  if(m) return m[1]+' × '+(T[compact(m[2])]||compact(m[2]));

  return s;
}

function replacePreserve(raw,lang){
  const value=String(raw??'');
  const lead=(value.match(/^\s*/)||[''])[0];
  const trail=(value.match(/\s*$/)||[''])[0];
  const core=value.slice(lead.length,value.length-trail.length);
  if(!core.trim()) return value;
  return lead+(lang==='ar'?dyn(core):core)+trail;
}

function translateTextNode(n,lang){
  if(!n || !n.parentElement || /^(SCRIPT|STYLE|NOSCRIPT|TEXTAREA|CODE|PRE)$/.test(n.parentElement.tagName)) return;
  let original=textCache.get(n);
  if(original===undefined){
    original=n.nodeValue;
    textCache.set(n,original);
  } else if(lang==='ar'){
    const expected=replacePreserve(original,'ar');
    if(n.nodeValue!==expected && n.nodeValue!==original){
      original=n.nodeValue;
      textCache.set(n,original);
    }
  }
  const next=lang==='ar'?replacePreserve(original,'ar'):original;
  if(n.nodeValue!==next) n.nodeValue=next;
}

function translateAttrs(el,lang){
  if(!(el instanceof Element)) return;
  let cache=attrCache.get(el);
  if(!cache){cache={};attrCache.set(el,cache);}

  ['placeholder','aria-label','title'].forEach(a=>{
    if(!el.hasAttribute(a)) return;
    if(cache[a]===undefined) cache[a]=el.getAttribute(a);
    const base=cache[a];
    el.setAttribute(a,lang==='ar'?dyn(base):base);
  });

  if(el.hasAttribute('data-lang-href-en')){
    el.setAttribute('href',lang==='ar'
      ?(el.getAttribute('data-lang-href-ar')||el.getAttribute('data-lang-href-en'))
      :el.getAttribute('data-lang-href-en'));
  }
}

function walk(root,lang){
  if(!root) return;
  if(root.nodeType===Node.TEXT_NODE){translateTextNode(root,lang);return;}
  if(!(root instanceof Element) && root!==document) return;
  if(root instanceof Element) translateAttrs(root,lang);

  const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  let n;
  while((n=w.nextNode())) translateTextNode(n,lang);
  if(root.querySelectorAll) root.querySelectorAll('*').forEach(el=>translateAttrs(el,lang));
}

function makeToggle(){
  const b=document.createElement('button');
  b.type='button';
  b.className='language-toggle nostrix-auto-language-toggle';
  b.setAttribute('data-nostrix-language-control','');
  return b;
}

function ensureToggle(){
  if(document.querySelector('.language-toggle')) return;

  const b=makeToggle();
  const navMenu=document.querySelector('.nav-menu');
  if(navMenu){
    b.classList.add('language-toggle-nav');
    navMenu.appendChild(b);
    return;
  }

  const topbar=document.querySelector('.topbar');
  if(topbar){
    b.classList.add('language-toggle-inline');
    topbar.appendChild(b);
    return;
  }

  /* Review and other compact pages use .nav instead of the main nav-menu. */
  const compactNav=document.querySelector('.nav');
  if(compactNav){
    b.classList.add('language-toggle-inline');
    const back=compactNav.querySelector('.back');
    if(back) compactNav.insertBefore(b,back);
    else compactNav.appendChild(b);
    return;
  }

  const header=document.querySelector('.shell > header, main.shell > header, body > header');
  if(header){
    b.classList.add('language-toggle-inline');
    header.appendChild(b);
    return;
  }

  b.classList.add('language-toggle-floating');
  document.body.appendChild(b);
}

function buttonState(){
  document.querySelectorAll('.language-toggle').forEach(b=>{
    const isArabic=current==='ar';
    const nextState=isArabic?'ar':'en';

    if(b.dataset.active!==nextState || !b.querySelector('.lang-switch')){
      b.dataset.active=nextState;
      b.innerHTML=
        '<span class="lang-label lang-en">EN</span>'+
        '<span class="lang-switch" aria-hidden="true"><span class="lang-switch-knob"></span></span>'+
        '<span class="lang-label lang-ar">AR</span>';
    }

    b.setAttribute('aria-label',isArabic?'Switch website to English':'تحويل الموقع إلى العربية');
    b.setAttribute('title',isArabic?'Switch to English':'Switch to Arabic');
  });
}

function bilingual(){
  document.querySelectorAll('[data-bilingual-ar]').forEach(e=>e.hidden=current==='ar');
  document.querySelectorAll('[data-bilingual-en]').forEach(e=>e.hidden=current!=='ar');
}

function loadArabicFont(){
  if(document.getElementById('nostrix-arabic-font')) return;
  const pre1=document.createElement('link');
  pre1.rel='preconnect';
  pre1.href='https://fonts.googleapis.com';
  document.head.appendChild(pre1);

  const pre2=document.createElement('link');
  pre2.rel='preconnect';
  pre2.href='https://fonts.gstatic.com';
  pre2.crossOrigin='anonymous';
  document.head.appendChild(pre2);

  const font=document.createElement('link');
  font.id='nostrix-arabic-font';
  font.rel='stylesheet';
  font.href='https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@300;400;500;600;700&display=swap';
  document.head.appendChild(font);
}

